let crypto;try{crypto=require("node:crypto")}catch(e){console.log("crypto not supported")}function generateRSAKeyPair(e){e=crypto.generateKeyPairSync("rsa",{modulusLength:e});return[e.publicKey,e.privateKey]}function sign(e){return crypto.sign("SHA256","abc",e)}function verify(e,o){return crypto.verify("SHA256","abc",e,o)}function generateECKeyPair(e){var o=["secp256k1","secp384r1","secp521r1"];if(o.includes(e))return[(e=crypto.generateKeyPairSync("ec",{namedCurve:e})).publicKey,e.privateKey];throw"Invalid Curve. Must be one of: "+o}function test(){var o,r,n=1e4;for(o of["secp256k1","secp384r1","secp521r1"]){var c=[],a=[];for(let e=0;e<5;e++){var s=generateECKeyPair(o),t=s[0],i=s[1],l=[],s=Date.now();for(let e=0;e<n;e++){var g=sign(i);l.push(g)}var u=(Date.now()-s)/1e3,u=(c.push(u),n/u);console.log(`ECDSA (${o}) signs/second: `+u),s=Date.now();for(let e=0;e<n;e++)verify(t,l[e]);u=(Date.now()-s)/1e3,s=(a.push(u),n/u);console.log(`ECDSA (${o}) verifications/second: `+s),console.log("")}console.log("5 run average:");var e=c.reduce((e,o)=>e+o,0)/5,v=n/(a.reduce((e,o)=>e+o,0)/5);console.log(`	ECDSA (${o}) average signs/second: `+n/e),console.log(`	ECDSA (${o}) average verifications/second: `+v)}for(r of[2048,3072,4096]){var p=[],f=[];for(let e=0;e<5;e++){var y=generateRSAKeyPair(r),d=y[0],S=y[1],A=[],y=Date.now();for(let e=0;e<n;e++){var D=sign(S);A.push(D)}var K=(Date.now()-y)/1e3,K=(p.push(K),n/K);console.log(`RSA (${r}) signs/second: `+K),y=Date.now();for(let e=0;e<n;e++)verify(d,A[e]);K=(Date.now()-y)/1e3,y=(f.push(K),n/K);console.log(`RSA (${r}) verifications/second: `+y),console.log("")}console.log("5 run average:");var h=p.reduce((e,o)=>e+o,0)/5,w=n/(f.reduce((e,o)=>e+o,0)/5);console.log(`	RSA (${r}) average signs/second: `+n/h),console.log(`	RSA (${r}) average verifications/second: `+w)}}test();